from flair.data import Sentence
tagger = get_plugin('tag')
if tagger is None:
    raise RuntimeError('Flair tagger plugin not loaded. Install flair and place model under models/hunflair2-ner/')
labels = state.get('labels') or 'Chemical,Disease'
if isinstance(labels, str):
    labels = [x.strip() for x in labels.split(',') if x.strip()]
text = state.get('text') or ''
import re
sents = [s.strip() for s in re.split(r'(?<=[.!?])\s+', text) if s.strip()]
if not sents:
    sents = [text]
__result__ = {lb: [] for lb in labels}
seen = {lb: set() for lb in labels}
for sent_text in sents:
    s = Sentence(sent_text)
    tagger.predict(s)
    for span in s.get_spans('ner'):
        tag = span.tag
        if tag in __result__ and span.text not in seen[tag]:
            seen[tag].add(span.text)
            __result__[tag].append(span.text)
